{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Esaxerenone, a close structural analogue sharing the ortho-methyl-biphenyl amide scaffold, has an absolute oral bioavailability of approximately 90% in healthy subjects, strongly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Asciminib, the highest-similarity retrieved analogue, has an absolute bioavailability of approximately 73% in humans, supporting high oral absorption for this amide/heteroaryl class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Netupitant, a moderately similar lipophilic amide with aryl trifluoromethyl/heteroaryl motifs, has a high absolute bioavailability of 63–87% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Conivaptan, a moderately similar amide with a lipophilic biphenyl-like core, has an absolute oral bioavailability of 44% in healthy subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: multiple structurally related analogues have absolute oral bioavailability values of 44–90%, especially esaxerenone (~90%) and asciminib (~73%). Low-F analogues are structurally distant and do not outweigh this evidence; the query is expected to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "The closest analogues have moderate Morgan similarity (0.23–0.31); differences in the pyridine/morpholine substituent and trifluoromethoxy position could affect absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

